  revealCount: document.querySelectorAll('[data-reveal].is-visible').length,
  totalRevealCount: document.querySelectorAll('[data-reveal]').length,
}));
console.log(JSON.stringify({ screenshot, state, snapshot: snapshot.full.slice(0, 6000) }, null, 2));
EOF

