const page = await browser.getPage("elysian-desktop");
await page.getByRole("link", { name: "Formula" }).click();
await page.waitForTimeout(1100);
const before = await page.evaluate(() => document.querySelector('.formula__description h3')?.textContent);
await page.locator('.note').nth(1).click();
await page.waitForTimeout(250);
const after = await page.evaluate(() => ({
  hash: location.hash,
  scrollY: Math.round(window.scrollY),
  heading: document.querySelector('.formula__description h3')?.textContent,
  detail: document.querySelector('.formula__description span')?.textContent,
  pressed: Array.from(document.querySelectorAll('.note')).map((node) => node.getAttribute('aria-pressed')),
}));
const screenshot = await saveScreenshot(await page.screenshot(), "elysian-desktop-formula.png");
console.log(JSON.stringify({ screenshot, before, after }, null, 2));
EOF

