@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";
@import "@fontsource-variable/geist";
@import "@fontsource-variable/bodoni-moda";

:root {
  --night: #031e28;
  --deep: #00141b;
  --petrol: #075268;
  --mist: #dfe9e7;
  --ice: #f0f5f2;
  --petal: #ff5576;
  --saffron: #f2a318;
  --ink: #082d39;
  --white: #f8fbf8;
  --line: rgba(8, 45, 57, 0.22);
  color: var(--ink);
  background: var(--mist);
  font-family: "Geist Variable", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  --page-shift: 0px;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  background: var(--deep);
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--mist);
}

body,
button,
input {
  font-family: "Geist Variable", sans-serif;
}

button,
a,
input {
  -webkit-tap-highlight-color: transparent;
}

button,
a {
  color: inherit;
}

button {
  cursor: pointer;
}

button:focus-visible,
a:focus-visible,
input:focus-visible {
  outline: 2px solid var(--petal);
  outline-offset: 4px;
}

::selection {
  color: var(--deep);
  background: var(--saffron);
}

main {
  position: relative;
  overflow: clip;
  background: var(--mist);
}

.page-progress {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 200;
  width: 100%;
  height: 3px;
  background: rgba(255, 255, 255, 0.14);
}

.page-progress__fill {
  width: 100%;
  height: 100%;
  background: var(--petal);
  transform: scaleX(0);
  transform-origin: left center;
  will-change: transform;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 100;
  display: grid;
  grid-template-columns: 52px 1fr auto;
  align-items: center;
  gap: 22px;
  width: 100%;
  padding: 18px 28px;
  color: white;
  mix-blend-mode: difference;
}

.nav__monogram {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
  text-decoration: none;
}

.nav__monogram span {
  font-family: "Bodoni Moda Variable", serif;
  font-size: 1.3rem;
  font-style: italic;
  line-height: 1;
}

.nav__edition,
.nav__links a,
.hero__meta,
.kicker,
.vertical-copy,
.triptych__panel span,
.note__index,
.note__label,
.edition__facts span,
.request-form label,
.footer__bottom,
.edition__caption {
  font-size: 0.66rem;
  font-weight: 560;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.nav__edition {
  margin: 0;
}

.nav__links {
  display: flex;
  align-items: center;
  gap: clamp(18px, 2.5vw, 42px);
}

.nav__links a {
  position: relative;
  text-decoration: none;
}

.nav__links a:not(.nav__cta)::after {
  position: absolute;
  right: 0;
  bottom: -4px;
  left: 0;
  height: 1px;
  background: currentColor;
  content: "";
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 300ms ease;
}

.nav__links a:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

.nav__cta {
  padding: 11px 15px;
  border: 1px solid currentColor;
  border-radius: 999px;
}

.hero {
  --lens-x: 68%;
  --lens-y: 37%;
  --lens-bg-x: 68%;
  --lens-bg-y: 37%;
  --lens-opacity: 0;
  position: relative;
  height: 100svh;
  min-height: 700px;
  overflow: hidden;
  color: var(--white);
  background: var(--petrol);
  isolation: isolate;
}

.hero__art {
  position: absolute;
  inset: 0;
  z-index: -3;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 50%;
  animation: hero-enter 1.8s cubic-bezier(0.22, 1, 0.36, 1) both;
  filter: saturate(0.92) contrast(1.03);
  transform: scale(1.045);
}

.hero__veil {
  position: absolute;
  inset: 0;
  z-index: -2;
  background:
    linear-gradient(180deg, rgba(0, 15, 20, 0.5) 0%, transparent 34%, transparent 54%, rgba(0, 13, 18, 0.76) 100%),
    linear-gradient(90deg, rgba(0, 18, 24, 0.35) 0%, transparent 40%, rgba(0, 16, 22, 0.12) 100%);
}

.hero__veil::after {
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.18'/%3E%3C/svg%3E");
  content: "";
  mix-blend-mode: soft-light;
  opacity: 0.24;
  pointer-events: none;
}

.hero__lens {
  position: absolute;
  top: var(--lens-y);
  left: var(--lens-x);
  z-index: -1;
  display: grid;
  width: clamp(160px, 17vw, 260px);
  aspect-ratio: 1;
  place-items: end center;
  padding-bottom: 22px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.75);
  border-radius: 50%;
  opacity: var(--lens-opacity);
  background-image: url('/elysian-botanical.jpg');
  background-position: var(--lens-bg-x) var(--lens-bg-y);
  background-size: 114% 114%;
  box-shadow: inset 0 0 0 7px rgba(255, 255, 255, 0.08), 0 20px 80px rgba(0, 0, 0, 0.22);
  filter: saturate(1.4) brightness(1.12);
  pointer-events: none;
  transform: translate(-50%, -50%);
  transition: opacity 350ms ease;
  will-change: top, left, background-position;
}

.hero__lens::before,
.hero__lens::after {
  position: absolute;
  top: 50%;
  left: 50%;
  background: rgba(255, 255, 255, 0.74);
  content: "";
  transform: translate(-50%, -50%);
}

.hero__lens::before {
  width: 20px;
  height: 1px;
}

.hero__lens::after {
  width: 1px;
  height: 20px;
}

.hero__lens span {
  font-size: 0.56rem;
  font-weight: 650;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.hero__meta {
  position: absolute;
  top: 17%;
  display: flex;
  flex-direction: column;
  gap: 7px;
  animation: fade-up 1s 1.2s both;
}

.hero__meta--left {
  left: 30px;
}

.hero__meta--right {
  right: 30px;
  text-align: right;
}

.hero__statement {
  position: absolute;
  right: 26px;
  bottom: 28px;
  left: 26px;
}

.hero__eyebrow {
  margin: 0 0 clamp(18px, 3vh, 32px) 0.6vw;
  font-family: "Bodoni Moda Variable", serif;
  font-size: clamp(1.25rem, 2.4vw, 2.4rem);
  font-style: italic;
  letter-spacing: -0.03em;
  animation: fade-up 1s 0.75s both;
}

.hero__word {
  display: flex;
  justify-content: space-between;
  margin: 0;
  font-family: "Bodoni Moda Variable", serif;
  font-size: clamp(5rem, 15.9vw, 17rem);
  font-weight: 450;
  letter-spacing: -0.085em;
  line-height: 0.67;
  text-transform: uppercase;
  white-space: nowrap;
}

.hero__word span {
  display: inline-block;
  animation: letter-rise 1.25s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.hero__word span:nth-child(1) { animation-delay: 120ms; }
.hero__word span:nth-child(2) { animation-delay: 180ms; }
.hero__word span:nth-child(3) { animation-delay: 240ms; }
.hero__word span:nth-child(4) { animation-delay: 300ms; }
.hero__word span:nth-child(5) { animation-delay: 360ms; }
.hero__word span:nth-child(6) { animation-delay: 420ms; }
.hero__word span:nth-child(7) { animation-delay: 480ms; }

.hero__foot {
  display: grid;
  grid-template-columns: minmax(280px, 430px) auto;
  align-items: end;
  justify-content: space-between;
  gap: 30px;
  margin-top: clamp(20px, 4vh, 42px);
  padding: 0 0.7vw;
  animation: fade-up 1s 1s both;
}

.hero__foot p {
  max-width: 420px;
  margin: 0;
  font-size: clamp(0.9rem, 1.1vw, 1.08rem);
  line-height: 1.45;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 18px;
  padding-bottom: 5px;
  border-bottom: 1px solid currentColor;
  font-size: 0.72rem;
  font-weight: 650;
  letter-spacing: 0.14em;
  text-decoration: none;
  text-transform: uppercase;
  transition: gap 250ms ease;
}

.text-link:hover {
  gap: 26px;
}

.hero__scroll {
  position: absolute;
  top: 48%;
  left: 29px;
  display: flex;
  align-items: center;
  gap: 15px;
  font-size: 0.57rem;
  font-weight: 650;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  transform: rotate(-90deg) translateX(-50%);
  transform-origin: left center;
}

.hero__scroll i {
  position: relative;
  display: block;
  width: 48px;
  height: 1px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.35);
}

.hero__scroll i::after {
  position: absolute;
  inset: 0;
  background: white;
  content: "";
  animation: scroll-line 1.8s ease-in-out infinite;
  transform: translateX(-100%);
}

.section-shell {
  width: min(100%, 1600px);
  margin: 0 auto;
  padding-right: clamp(24px, 5vw, 88px);
  padding-left: clamp(24px, 5vw, 88px);
}

.manifesto {
  display: grid;
  grid-template-columns: 24% 1fr;
  min-height: 88vh;
  padding-top: clamp(110px, 16vw, 230px);
  padding-bottom: clamp(110px, 14vw, 210px);
  background: var(--mist);
}

.manifesto__aside {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  border-right: 1px solid var(--line);
}

.kicker {
  margin: 0;
  color: rgba(8, 45, 57, 0.68);
}

.vertical-copy {
  position: absolute;
  bottom: 0;
  left: 0;
  color: rgba(8, 45, 57, 0.55);
  writing-mode: vertical-rl;
  transform: rotate(180deg);
}

.manifesto__copy {
  padding-left: clamp(34px, 7vw, 110px);
}

.manifesto__lead {
  margin: 0 0 0.15em;
  color: var(--petal);
  font-family: "Bodoni Moda Variable", serif;
  font-size: clamp(2.6rem, 6.2vw, 7.2rem);
  font-style: italic;
  letter-spacing: -0.065em;
  line-height: 0.88;
}

.manifesto h2,
.formula h2,
.edition h2 {
  margin: 0;
  font-family: "Bodoni Moda Variable", serif;
  font-weight: 440;
  letter-spacing: -0.065em;
  line-height: 0.88;
}

.manifesto h2 {
  max-width: 1000px;
  font-size: clamp(3.7rem, 8vw, 9rem);
}

.manifesto__body {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(30px, 6vw, 90px);
  max-width: 870px;
  margin: clamp(60px, 8vw, 110px) 0 0 auto;
}

.manifesto__body p {
  margin: 0;
  font-size: clamp(1rem, 1.28vw, 1.22rem);
  line-height: 1.6;
}

.triptych {
  display: flex;
  height: min(92vh, 980px);
  min-height: 620px;
  gap: 3px;
  padding: 3px;
  overflow: hidden;
  background: var(--deep);
}

.triptych__panel {
  position: relative;
  flex: 1;
  overflow: hidden;
  background-color: var(--petrol);
  background-image: linear-gradient(180deg, transparent 60%, rgba(0, 15, 20, 0.75)), url('/elysian-botanical.jpg');
  background-repeat: no-repeat;
  background-size: auto 100%;
  transition: flex 700ms cubic-bezier(0.16, 1, 0.3, 1), filter 700ms ease;
  filter: saturate(0.82);
}

.triptych__panel::after {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(255, 255, 255, 0.12);
  content: "";
  pointer-events: none;
}

.triptych__panel:hover {
  flex: 1.28;
  filter: saturate(1.1);
}

.triptych__panel--one { background-position: 4% 50%; transition-delay: 0ms; }
.triptych__panel--two { background-position: 50% 50%; transition-delay: 100ms; }
.triptych__panel--three { background-position: 96% 50%; transition-delay: 200ms; }

.triptych__panel span {
  position: absolute;
  bottom: 26px;
  left: 26px;
  color: white;
}

.formula {
  position: relative;
  padding-top: clamp(100px, 13vw, 190px);
  padding-bottom: clamp(110px, 14vw, 210px);
  color: var(--white);
  background: var(--night);
}

.formula::before {
  position: absolute;
  top: 8%;
  right: -7vw;
  width: 34vw;
  aspect-ratio: 1;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 50%;
  content: "";
}

.formula .kicker {
  margin-bottom: 34px;
  color: var(--saffron);
}

.formula h2 {
  max-width: 1040px;
  font-size: clamp(3.4rem, 7.8vw, 8.5rem);
}

.formula__content {
  display: grid;
  grid-template-columns: minmax(380px, 0.85fr) minmax(440px, 1.15fr);
  gap: clamp(60px, 8vw, 130px);
  align-items: stretch;
  margin-top: clamp(80px, 11vw, 160px);
}

.notes {
  border-top: 1px solid rgba(255, 255, 255, 0.25);
}

.note {
  display: grid;
  grid-template-columns: 45px 120px 1fr 22px;
  align-items: center;
  width: 100%;
  min-height: 112px;
  padding: 12px 0;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.25);
  color: rgba(255, 255, 255, 0.58);
  text-align: left;
  background: transparent;
  transition: color 300ms ease, padding 300ms ease;
}

.note:hover,
.note.is-active {
  color: white;
  padding-left: 12px;
}

.note.is-active .note__index,
.note.is-active .note__mark {
  color: var(--saffron);
}

.note strong {
  font-family: "Bodoni Moda Variable", serif;
  font-size: clamp(1.7rem, 2.3vw, 2.55rem);
  font-weight: 470;
  letter-spacing: -0.045em;
}

.note__label {
  font-size: 0.57rem;
}

.note__mark {
  font-size: 1.4rem;
  font-weight: 250;
  transition: transform 400ms ease;
}

.note.is-active .note__mark {
  transform: rotate(45deg);
}

.formula__specimen {
  display: grid;
  grid-template-rows: 1fr auto;
  min-height: 520px;
  padding: 28px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  background: rgba(255, 255, 255, 0.018);
}

.specimen {
  position: relative;
  display: grid;
  width: min(26vw, 360px);
  aspect-ratio: 1;
  place-items: center;
  align-self: center;
  justify-self: center;
  transition: filter 500ms ease;
}

.specimen__orbit {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: 50%;
}

.specimen__orbit--outer {
  animation: spin 18s linear infinite;
}

.specimen__orbit--outer::before,
.specimen__orbit--inner::before {
  position: absolute;
  top: 50%;
  left: -5px;
  width: 9px;
  aspect-ratio: 1;
  border-radius: 50%;
  background: var(--saffron);
  content: "";
}

.specimen__orbit--inner {
  inset: 14%;
  border-style: dashed;
  opacity: 0.55;
  animation: spin 12s linear infinite reverse;
}

.specimen__orbit--inner::before {
  background: var(--petal);
}

.specimen__core {
  width: 48%;
  aspect-ratio: 1;
  border-radius: 50% 42% 55% 45%;
  background-image: url('/elysian-botanical.jpg');
  background-size: 650%;
  box-shadow: 0 20px 80px rgba(0, 0, 0, 0.42);
  animation: breathe 6s ease-in-out infinite;
  transition: background-position 700ms cubic-bezier(0.16, 1, 0.3, 1), border-radius 700ms ease;
}

.specimen--1 .specimen__core { background-position: 42% 42%; }
.specimen--2 .specimen__core { background-position: 81% 31%; border-radius: 48% 55% 38% 62%; }
.specimen--3 .specimen__core { background-position: 60% 70%; border-radius: 38% 62% 54% 46%; }

.specimen > span {
  position: absolute;
  z-index: 1;
  color: white;
  font-family: "Bodoni Moda Variable", serif;
  font-size: 3.4rem;
  font-style: italic;
}

.formula__description {
  display: grid;
  grid-template-columns: 110px minmax(150px, 0.65fr) 1fr;
  gap: 24px;
  align-items: baseline;
  padding-top: 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.22);
}

.formula__description p,
.formula__description span {
  margin: 0;
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.72rem;
  line-height: 1.5;
}

.formula__description p {
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.formula__description h3 {
  margin: 0;
  font-family: "Bodoni Moda Variable", serif;
  font-size: 1.45rem;
  font-weight: 450;
  letter-spacing: -0.04em;
}

.ribbon {
  position: relative;
  z-index: 2;
  width: 110%;
  margin-left: -5%;
  padding: 18px 0;
  overflow: hidden;
  color: var(--deep);
  background: var(--saffron);
  transform: rotate(-1.5deg);
}

.ribbon > div {
  display: flex;
  width: max-content;
  align-items: center;
  animation: marquee 24s linear infinite;
}

.ribbon span {
  padding: 0 25px;
  font-size: clamp(0.75rem, 1vw, 0.95rem);
  font-weight: 680;
  letter-spacing: 0.18em;
}

.ribbon i {
  color: var(--petal);
  font-style: normal;
}

.edition {
  display: grid;
  grid-template-columns: minmax(460px, 1fr) minmax(420px, 0.9fr);
  gap: clamp(70px, 10vw, 170px);
  align-items: center;
  padding-top: clamp(120px, 15vw, 220px);
  padding-bottom: clamp(120px, 15vw, 220px);
  background: var(--mist);
}

.edition__visual {
  position: relative;
  display: grid;
  min-height: 760px;
  place-items: center;
  overflow: hidden;
  background: var(--petrol);
}

.edition__visual::before {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(2, 34, 43, 0.2), rgba(0, 13, 18, 0.62)),
    url('/elysian-botanical.jpg') center / cover;
  content: "";
  filter: blur(1.5px) saturate(0.7) brightness(0.72);
  transform: scale(1.07) translateY(calc(var(--page-shift) * -0.08));
}

.edition__visual::after {
  position: absolute;
  inset: 18px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  content: "";
}

.edition__halo {
  position: absolute;
  z-index: 1;
  width: 64%;
  aspect-ratio: 1;
  border: 1px solid rgba(255, 255, 255, 0.55);
  border-radius: 50%;
  box-shadow: 0 0 100px rgba(255, 85, 118, 0.24);
  animation: breathe 7s ease-in-out infinite;
}

.bottle {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(48%, 300px);
  filter: drop-shadow(0 30px 36px rgba(0, 0, 0, 0.42));
}

.bottle__cap {
  z-index: 3;
  width: 43%;
  height: 94px;
  border: 1px solid rgba(255, 255, 255, 0.35);
  background: linear-gradient(90deg, #01161e, #0c3947 45%, #001017);
  box-shadow: inset 8px 0 20px rgba(255, 255, 255, 0.07);
}

.bottle__neck {
  width: 29%;
  height: 42px;
  border-right: 1px solid rgba(255, 255, 255, 0.28);
  border-left: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(220, 240, 238, 0.08);
}

.bottle__glass {
  position: relative;
  width: 100%;
  aspect-ratio: 0.66;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.48);
  border-radius: 8% 8% 5% 5% / 5% 5% 3% 3%;
  background: linear-gradient(90deg, rgba(255,255,255,.16), rgba(255,255,255,.03) 18%, rgba(255,255,255,.02) 78%, rgba(255,255,255,.14));
  box-shadow: inset 0 0 34px rgba(255, 255, 255, 0.09);
  backdrop-filter: blur(8px);
}

.bottle__liquid {
  position: absolute;
  right: 8px;
  bottom: 8px;
  left: 8px;
  height: 76%;
  border-radius: 2% 2% 4% 4%;
  background: linear-gradient(180deg, rgba(236, 153, 23, 0.12), rgba(255, 71, 101, 0.38));
  box-shadow: inset 0 16px 24px rgba(255, 209, 129, 0.09);
}

.bottle__shine {
  position: absolute;
  top: 7%;
  bottom: 8%;
  left: 8%;
  z-index: 3;
  width: 2px;
  background: linear-gradient(180deg, transparent, rgba(255,255,255,.7), transparent);
}

.bottle__label {
  position: absolute;
  top: 50%;
  left: 50%;
  z-index: 4;
  display: flex;
  width: 72%;
  aspect-ratio: 0.92;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, 0.8);
  color: white;
  background:
    linear-gradient(rgba(3, 30, 40, 0.34), rgba(3, 30, 40, 0.34)),
    url('/elysian-botanical.jpg') 50% 45% / 470%;
  box-shadow: 0 12px 28px rgba(0,0,0,.18);
  text-align: center;
  transform: translate(-50%, -50%);
}

.bottle__label span {
  font-family: "Bodoni Moda Variable", serif;
  font-size: clamp(1.25rem, 2vw, 2rem);
  letter-spacing: 0.08em;
}

.bottle__label i {
  margin-top: 12px;
  font-family: "Bodoni Moda Variable", serif;
  font-size: 0.72rem;
  letter-spacing: 0.1em;
}

.bottle__label strong {
  margin-top: 2px;
  font-family: "Bodoni Moda Variable", serif;
  font-size: clamp(1.8rem, 3vw, 3.2rem);
  font-weight: 440;
  line-height: 1;
}

.bottle__label small {
  margin-top: 15px;
  font-size: 0.42rem;
  font-weight: 650;
  letter-spacing: 0.18em;
}

.edition__caption {
  position: absolute;
  bottom: 32px;
  left: 37px;
  z-index: 4;
  margin: 0;
  color: white;
}

.edition__copy .kicker {
  margin-bottom: 34px;
  color: var(--petal);
}

.edition h2 {
  font-size: clamp(3.5rem, 6.2vw, 7rem);
}

.edition__intro {
  max-width: 610px;
  margin: 55px 0;
  font-size: clamp(1.04rem, 1.34vw, 1.28rem);
  line-height: 1.62;
}

.edition__facts {
  border-top: 1px solid var(--line);
}

.edition__facts > div {
  display: grid;
  grid-template-columns: 42% 1fr;
  align-items: center;
  min-height: 64px;
  border-bottom: 1px solid var(--line);
}

.edition__facts span {
  color: rgba(8, 45, 57, 0.58);
}

.edition__facts strong {
  font-family: "Bodoni Moda Variable", serif;
  font-size: 1.05rem;
  font-weight: 520;
}

.request-form {
  margin-top: 58px;
}

.request-form label {
  display: block;
  margin-bottom: 14px;
}

.request-form__field {
  display: grid;
  grid-template-columns: 1fr auto;
  border-bottom: 1px solid var(--ink);
}

.request-form input {
  min-width: 0;
  padding: 17px 0;
  border: 0;
  color: var(--ink);
  font-size: 1rem;
  background: transparent;
  outline: none;
}

.request-form input::placeholder {
  color: rgba(8, 45, 57, 0.45);
}

.request-form button {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 10px 0 10px 30px;
  border: 0;
  color: var(--ink);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  background: transparent;
}

.request-form button i {
  display: grid;
  width: 42px;
  aspect-ratio: 1;
  place-items: center;
  border-radius: 50%;
  color: white;
  font-size: 1rem;
  font-style: normal;
  background: var(--petal);
  transition: transform 250ms ease;
}

.request-form button:hover i {
  transform: rotate(45deg);
}

.joined {
  display: flex;
  gap: 20px;
  align-items: center;
  margin-top: 58px;
  padding: 24px;
  color: white;
  background: var(--ink);
  animation: fade-up 600ms both;
}

.joined > span {
  color: var(--saffron);
  font-size: 1.5rem;
}

.joined strong {
  font-family: "Bodoni Moda Variable", serif;
  font-size: 1.25rem;
  font-weight: 480;
}

.joined p {
  margin: 3px 0 0;
  color: rgba(255, 255, 255, 0.64);
  font-size: 0.82rem;
}

.footer {
  padding: 46px clamp(24px, 4vw, 64px) 24px;
  overflow: hidden;
  color: var(--white);
  background: var(--deep);
}

.footer__top,
.footer__bottom {
  display: flex;
  justify-content: space-between;
  gap: 30px;
}

.footer__top {
  align-items: center;
  padding-bottom: 52px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.18);
}

.footer__top p {
  margin: 0;
  font-family: "Bodoni Moda Variable", serif;
  font-size: clamp(1.25rem, 2vw, 2rem);
  font-style: italic;
}

.footer__top div {
  display: flex;
  gap: 32px;
}

.footer__top a {
  font-size: 0.65rem;
  font-weight: 620;
  letter-spacing: 0.13em;
  text-decoration: none;
  text-transform: uppercase;
}

.footer__word {
  margin: 0.22em 0 -0.04em;
  font-family: "Bodoni Moda Variable", serif;
  font-size: clamp(5.8rem, 18.5vw, 20rem);
  font-weight: 450;
  letter-spacing: -0.09em;
  line-height: 0.9;
  text-align: center;
  white-space: nowrap;
}

.footer__bottom {
  padding-top: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.18);
  color: rgba(255, 255, 255, 0.5);
}

[data-reveal] {
  opacity: 0;
  transform: translateY(36px);
  transition: opacity 900ms ease, transform 1s cubic-bezier(0.16, 1, 0.3, 1);
}

[data-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}

@keyframes hero-enter {
  from { opacity: 0; transform: scale(1.12); }
  to { opacity: 1; transform: scale(1.045); }
}

@keyframes letter-rise {
  from { opacity: 0; transform: translateY(70%) rotate(3deg); }
  to { opacity: 1; transform: translateY(0) rotate(0); }
}

@keyframes fade-up {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes scroll-line {
  0%, 20% { transform: translateX(-100%); }
  70%, 100% { transform: translateX(100%); }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@keyframes breathe {
  0%, 100% { transform: scale(0.96) rotate(-2deg); }
  50% { transform: scale(1.04) rotate(2deg); }
}

@keyframes marquee {
  to { transform: translateX(-50%); }
}

@media (max-width: 1100px) {
  .nav__edition {
    display: none;
  }

  .nav {
    grid-template-columns: 52px 1fr;
  }

  .nav__links {
    justify-self: end;
  }

  .formula__content,
  .edition {
    grid-template-columns: 1fr;
  }

  .formula__specimen {
    min-height: 580px;
  }

  .specimen {
    width: min(52vw, 370px);
  }

  .edition__visual {
    width: min(100%, 760px);
    min-height: 820px;
    justify-self: center;
  }

  .edition__copy {
    max-width: 760px;
    justify-self: center;
  }
}

@media (max-width: 760px) {
  .nav {
    grid-template-columns: 44px 1fr;
    gap: 14px;
    padding: 14px 17px;
  }

  .nav__monogram {
    width: 42px;
    height: 42px;
  }

  .nav__links a:not(.nav__cta) {
    display: none;
  }

  .nav__cta {
    padding: 9px 12px;
    font-size: 0.56rem !important;
  }

  .hero {
    min-height: 690px;
  }

  .hero__art {
    object-position: 56% center;
  }

  .hero__meta {
    top: 17%;
    font-size: 0.55rem;
  }

  .hero__meta--left {
    left: 18px;
  }

  .hero__meta--right {
    right: 18px;
  }

  .hero__meta span:nth-child(2) {
    display: none;
  }

  .hero__statement {
    right: 16px;
    bottom: 24px;
    left: 16px;
  }

  .hero__eyebrow {
    max-width: 270px;
    font-size: 1.35rem;
  }

  .hero__word {
    font-size: 17.2vw;
    line-height: 0.72;
  }

  .hero__foot {
    grid-template-columns: 1fr;
    gap: 24px;
    margin-top: 28px;
  }

  .hero__foot p {
    max-width: 320px;
    font-size: 0.83rem;
  }

  .hero__foot .text-link {
    justify-self: start;
  }

  .hero__scroll {
    display: none;
  }

  .hero__lens {
    top: 32%;
    left: 63%;
    width: 150px;
    opacity: 0.7;
    background-position: 62% 34%;
  }

  .manifesto {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .manifesto__aside {
    min-height: 80px;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .vertical-copy {
    right: 0;
    bottom: auto;
    left: auto;
    writing-mode: horizontal-tb;
    transform: none;
  }

  .manifesto__copy {
    padding-top: 54px;
    padding-left: 0;
  }

  .manifesto__lead {
    font-size: clamp(2.8rem, 13vw, 4.6rem);
  }

  .manifesto h2 {
    font-size: clamp(4rem, 16vw, 6rem);
  }

  .manifesto__body {
    grid-template-columns: 1fr;
    gap: 24px;
    margin-top: 54px;
  }

  .triptych {
    flex-direction: column;
    height: 950px;
    min-height: 0;
  }

  .triptych__panel {
    min-height: 0;
    background-size: 145% auto;
  }

  .triptych__panel:hover {
    flex: 1;
  }

  .triptych__panel--one { background-position: 12% 28%; }
  .triptych__panel--two { background-position: 52% 56%; }
  .triptych__panel--three { background-position: 88% 65%; }

  .formula h2,
