:root {
  --night: #031e28;
  --deep: #00141b;
  --petrol: #075268;
  --mist: #dfe9e7;
  --ice: #f0f5f2;
  --petal: #ff5576;
  --saffron: #f2a318;
  --ink: #082d39;
  --white: #f8fbf8;
  --line: rgba(8, 45, 57, 0.22);
  color: var(--ink);
  background: var(--mist);
  font-family: "Geist Variable", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  --page-shift: 0px;
}
* {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
  background: var(--deep);
}
body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--mist);
}
body, button, input {
  font-family: "Geist Variable", sans-serif;
}
button, a, input {
  -webkit-tap-highlight-color: transparent;
}
button, a {
  color: inherit;
}
button {
  cursor: pointer;
}
button:focus-visible, a:focus-visible, input:focus-visible {
  outline: 2px solid var(--petal) !important;
  outline-offset: 4px;
  box-shadow: 0 0 0 4px var(--saffron);
  @supports (color: color-mix(in lab, red, red)) {
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--saffron) 72%, transparent);
  }
}
::selection {
  color: var(--deep);
  background: var(--saffron);
}
main {
  position: relative;
  overflow: clip;
  background: var(--mist);
}
.page-progress {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 200;
  width: 100%;
  height: 3px;
  background: rgba(255, 255, 255, 0.14);
}
.page-progress__fill {
  width: 100%;
  height: 100%;
  background: var(--petal);
  transform: scaleX(0);
  transform-origin: left center;
  will-change: transform;
}
.nav {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 100;
  display: grid;
  grid-template-columns: 52px 1fr auto;
  align-items: center;
  gap: 22px;
  width: 100%;
  padding: 18px 28px;
  color: white;
  mix-blend-mode: difference;
}
.nav__monogram {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
  text-decoration: none;
}
.nav__monogram span {
  font-family: "Bodoni Moda Variable", serif;
  font-size: 1.3rem;
  font-style: italic;
  line-height: 1;
}
.nav__edition, .nav__links a, .hero__meta, .kicker, .vertical-copy, .triptych__panel span, .note__index, .note__label, .edition__facts span, .request-form label, .footer__bottom, .edition__caption {
  font-size: 0.66rem;
  font-weight: 560;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.nav__edition {
  margin: 0;
}
.nav__links {
  display: flex;
  align-items: center;
  gap: clamp(18px, 2.5vw, 42px);
}
.nav__links a {
  position: relative;
  text-decoration: none;
}
.nav__links a:not(.nav__cta)::after {
  position: absolute;
  right: 0;
  bottom: -4px;
  left: 0;
  height: 1px;
  background: currentColor;
  content: "";
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 300ms ease;
}
.nav__links a:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}
.nav__cta {
  padding: 11px 15px;
  border: 1px solid currentColor;
  border-radius: 999px;
}
.hero {
  --lens-x: 68%;
  --lens-y: 37%;
  --lens-bg-x: 68%;
  --lens-bg-y: 37%;
  --lens-opacity: 0;
  position: relative;
  height: 100svh;
  min-height: 700px;
  overflow: hidden;
  color: var(--white);
  background: var(--petrol);
  isolation: isolate;
}
.hero__art {
  position: absolute;
  inset: 0;
  z-index: -3;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 50%;
  animation: hero-enter 1.8s cubic-bezier(0.22, 1, 0.36, 1) both;
  filter: saturate(0.92) contrast(1.03);
  transform: scale(1.045);
}
.hero__veil {
  position: absolute;
  inset: 0;
  z-index: -2;
  background: linear-gradient(180deg, rgba(0, 15, 20, 0.5) 0%, transparent 34%, transparent 54%, rgba(0, 13, 18, 0.76) 100%), linear-gradient(90deg, rgba(0, 18, 24, 0.35) 0%, transparent 40%, rgba(0, 16, 22, 0.12) 100%);
}
.hero__veil::after {
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.18'/%3E%3C/svg%3E");
  content: "";
  mix-blend-mode: soft-light;
  opacity: 0.24;
  pointer-events: none;
}
.hero__lens {
  position: absolute;
  top: var(--lens-y);
  left: var(--lens-x);
  z-index: -1;
  display: grid;
  width: clamp(160px, 17vw, 260px);
  aspect-ratio: 1;
  place-items: end center;
  padding-bottom: 22px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.75);
  border-radius: 50%;
  opacity: var(--lens-opacity);
  background-image: url('/elysian-botanical.jpg');
  background-position: var(--lens-bg-x) var(--lens-bg-y);
  background-size: 114% 114%;
  box-shadow: inset 0 0 0 7px rgba(255, 255, 255, 0.08), 0 20px 80px rgba(0, 0, 0, 0.22);
  filter: saturate(1.4) brightness(1.12);
  pointer-events: none;
  transform: translate(-50%, -50%);
  transition: opacity 350ms ease;
  will-change: top, left, background-position;
}
.hero__lens::before, .hero__lens::after {
  position: absolute;
  top: 50%;
  left: 50%;
  background: rgba(255, 255, 255, 0.74);
  content: "";
  transform: translate(-50%, -50%);
}
.hero__lens::before {
  width: 20px;
  height: 1px;
}
.hero__lens::after {
  width: 1px;
  height: 20px;
}
.hero__lens span {
  font-size: 0.56rem;
  font-weight: 650;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.hero__meta {
  position: absolute;
  top: 17%;
  display: flex;
  flex-direction: column;
  gap: 7px;
  animation: fade-up 1s 1.2s both;
}
.hero__meta--left {
  left: 30px;
}
.hero__meta--right {
  right: 30px;
  text-align: right;
}
.hero__statement {
  position: absolute;
  right: 26px;
  bottom: 28px;
  left: 26px;
}
.hero__eyebrow {
  margin: 0 0 clamp(18px, 3vh, 32px) 0.6vw;
  font-family: "Bodoni Moda Variable", serif;
  font-size: clamp(1.25rem, 2.4vw, 2.4rem);
  font-style: italic;
  letter-spacing: -0.03em;
  animation: fade-up 1s 0.75s both;
}
.hero__word {
  display: flex;
  justify-content: space-between;
  margin: 0;
  font-family: "Bodoni Moda Variable", serif;
  font-size: clamp(5rem, 15.9vw, 17rem);
  font-weight: 450;
  letter-spacing: -0.085em;
  line-height: 0.67;
  text-transform: uppercase;
  white-space: nowrap;
}
.hero__word span {
  display: inline-block;
  animation: letter-rise 1.25s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.hero__word span:nth-child(1) {
  animation-delay: 120ms;
}
.hero__word span:nth-child(2) {
  animation-delay: 180ms;
}
.hero__word span:nth-child(3) {
  animation-delay: 240ms;
}
.hero__word span:nth-child(4) {
  animation-delay: 300ms;
}
.hero__word span:nth-child(5) {
  animation-delay: 360ms;
}
.hero__word span:nth-child(6) {
  animation-delay: 420ms;
}
.hero__word span:nth-child(7) {
  animation-delay: 480ms;
}
.hero__foot {
  display: grid;
  grid-template-columns: minmax(280px, 430px) auto;
  align-items: end;
  justify-content: space-between;
  gap: 30px;
  margin-top: clamp(20px, 4vh, 42px);
  padding: 0 0.7vw;
  animation: fade-up 1s 1s both;
}
.hero__foot p {
  max-width: 420px;
  margin: 0;
  font-size: clamp(0.9rem, 1.1vw, 1.08rem);
  line-height: 1.45;
}
.text-link {
  display: inline-flex;
  align-items: center;
  gap: 18px;
  padding-bottom: 5px;
  border-bottom: 1px solid currentColor;
  font-size: 0.72rem;
  font-weight: 650;
  letter-spacing: 0.14em;
  text-decoration: none;
  text-transform: uppercase;
  transition: gap 250ms ease;
}
.text-link:hover {
  gap: 26px;
}
.hero__scroll {
  position: absolute;
  top: 48%;
  left: 29px;
  display: flex;
  align-items: center;
  gap: 15px;
  font-size: 0.57rem;
  font-weight: 650;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  transform: rotate(-90deg) translateX(-50%);
  transform-origin: left center;
}
.hero__scroll i {
  position: relative;
  display: block;
  width: 48px;
  height: 1px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.35);
}
.hero__scroll i::after {
  position: absolute;
  inset: 0;
  background: white;
  content: "";
  animation: scroll-line 1.8s ease-in-out infinite;
  transform: translateX(-100%);
}
.section-shell {
  width: min(100%, 1600px);
  margin: 0 auto;
  padding-right: clamp(24px, 5vw, 88px);
  padding-left: clamp(24px, 5vw, 88px);
}
.manifesto {
  display: grid;
  grid-template-columns: 24% 1fr;
  min-height: 88vh;
  padding-top: clamp(110px, 16vw, 230px);
  padding-bottom: clamp(110px, 14vw, 210px);
  background: var(--mist);
}
.manifesto__aside {
  position: relative;
  display: flex;
  flex-direction: column;
